query GetDefinitionProblems($kind: DefinitionKind!) {
  definitionProblems(kind: $kind) {
    kind
    definitionId
    code
    reason
    definitionPath
    packageRoot
    usingLastGood
    dependencyChain
    __typename
  }
}

